{"results": [{"id": "FAM:SF-APPS-024", "label": "Study family SF-APPS-024: DRIVE-as-BEST counter vs constrained mix", "score": 1.431, "reached_via": ["FAM:SF-APPS-023 auto_related_family (repeat_order_unknown) FAM:SF-APPS-024", "FAM:SF-APPS-023 auto_related_family (repeat_order_unknown) FAM:SF-APPS-024"], "attributes": {"observed_research_question": "DRIVE-as-BEST counter vs constrained mix", "auto_outcome_status": "untestable", "observed_hypothesis": "When BEST=DRIVE (counter_h2_n>=5), observed DRIVE H2 PPP beats a feasibility-constrained baseline.", "observed_result": "A mean=1.178 vs B_game 1.236 (gap=-0.058, p=0.6069) vs B_fixed 1.244 (gap=-0.066, p=0.2175) vs coach default C 1.134 (gap=+0.043, p=0.3052). MDE at 80% power ~0.180 PPP (SD~0.34).", "auto_failure_mechanism": "A_unanswerable (question not answerable with the data or design)", "observed_failure_evidence": "Observed gap -0.066 is below MDE 0.180; n=44 cannot distinguish a true null from an effect up to 0.18 PPP.", "observed_sample_and_power": "n=44; MDE 0.180 PPP at 80% power (SD~0.34); 0.265 if SD~0.5", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:low_power_large_MDE"}, {"rel": "auto_limited_by", "node": "LIM:small_sample"}, {"rel": "auto_has_risk", "node": "RISK:SAMPLE_SIZE_POWER"}]}, {"id": "FAM:SF-APPS-030", "label": "Study family SF-APPS-030: Coaching alignment: BEST/AVOID run rates vs series wins (55 series)", "score": 1.303, "reached_via": ["request matches the question or hypothesis of FAM:SF-APPS-030 (0.71)", "FAM:SF08 auto_related_family (record_link_extends) FAM:SF-APPS-030"], "attributes": {"observed_research_question": "Coaching alignment: BEST/AVOID run rates vs series wins (55 series)", "auto_outcome_status": "untestable", "observed_hypothesis": "Teams that run BEST counters more (and AVOID less) after suppression win more series.", "observed_result": "% ran BEST 44.7% of triggers / 9.7% volume; % ran AVOID 61.1% / 23.3% volume. Spearman BEST vs won rho=+0.131 p=0.1723; AVOID vs won rho=-0.098 p=0.3099. Mean PPP BEST 1.395 vs AVOID 0.865.", "auto_failure_mechanism": "A_unanswerable (question not answerable with the data or design)", "observed_failure_evidence": "Alignment-win Spearmans ns (p=0.172 / 0.310) at n=110 directions; INSUFF_EVIDENCE is 91.5% of triggers.", "observed_sample_and_power": "n=110 series-directions", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_verdict": "null", "observed_failure_type": "A_unanswerable"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:small_sample"}, {"rel": "auto_related_family", "node": "FAM:SF05"}]}, {"id": "FAM:SF-APPS-027", "label": "Study family SF-APPS-027: Adaptation quality vs talent as predictor of series wins", "score": 1.16, "reached_via": ["request matches RQC:RQC-082 (0.71); FAM:SF-APPS-027 auto_addresses_question RQC:RQC-082", "FAM:SF-APPS-030 auto_related_family (record_link_related_to) FAM:SF-APPS-027"], "attributes": {"observed_research_question": "Adaptation quality vs talent as predictor of series wins", "auto_outcome_status": "untestable", "observed_hypothesis": "pct_ran_BEST - pct_ran_AVOID predicts series wins after controlling for RS net-rating talent.", "observed_result": "corr(talent, adapt)=+0.124. Per-series logistic: talent_diff_z +0.737 p=0.0213; adapt_diff_z +0.328 p=0.2755. Team-in-series cluster: talent p=0.0095, adapt p=0.2449. Univariate adapt beta=+0.311 p=0.1128. LPM: talent +0 [cut; read_family for the full text]", "auto_failure_mechanism": "A_unanswerable (question not answerable with the data or design)", "observed_failure_evidence": "After talent control adapt p=0.275; n~55 series cannot separate coaching adaptation from roster quality.", "observed_sample_and_power": "n=55 series / 110 directions"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:confounding"}, {"rel": "auto_limited_by", "node": "LIM:small_sample"}, {"rel": "auto_has_risk", "node": "RISK:CONFOUNDING"}, {"rel": "auto_has_risk", "node": "RISK:SAMPLE_SIZE_POWER"}]}, {"id": "FAM:SF-APPS-023", "label": "Study family SF-APPS-023: System BEST vs constrained league mix (non-CUT matchup-specificity test)", "score": 1.073, "reached_via": ["request matches the question or hypothesis of FAM:SF-APPS-023 (0.72)", "request matches RQC:RQC-024 (0.71); FAM:SF-APPS-023 auto_addresses_question RQC:RQC-024"], "attributes": {"observed_research_question": "System BEST vs constrained league mix (non-CUT matchup-specificity test)", "auto_outcome_status": "rejected", "observed_hypothesis": "Matchup-specific (non-CUT) BEST counters beat a feasibility-weighted league mix that ignores game state.", "observed_result": "All BEST vs mix: 1.481 vs 1.212, gap=+0.269, p=0.0000, n=283. Non-CUT BEST vs mix: 1.216 vs 1.206, gap=+0.010, p=0.1709, n=136. L3_MATCHUP non-CUT: gap=+0.001, p=0.3277, n=47. BEST vs AVOID gap=+0.692, p=0.0000, n=169. 1 [cut; read_family for the full text]", "auto_failure_mechanism": "B_powered_null (adequately powered null result)", "observed_failure_evidence": "Key non-CUT test gap=+0.010, p=0.1709, n=136; H2H L3 non-CUT gap=+0.001, p=0.3277. Headline A vs B is CUT-driven.", "observed_sample_and_power": "n=136 non-CUT; n=47 L3 non-CUT"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:selection_or_regression_to_the_mean"}, {"rel": "auto_limited_by", "node": "LIM:small_sample"}, {"rel": "auto_has_risk", "node": "RISK:SAMPLE_SIZE_POWER"}]}, {"id": "FAM:SF05", "label": "Study family SF05: Coaching pickup: H1->H2 share shift toward BEST vs AVOID", "score": 1.07, "reached_via": ["FAM:SF-APPS-030 auto_related_family (record_link_related_to) FAM:SF05", "FAM:SF08 auto_related_family (repeated_by_later_family) FAM:SF05"], "attributes": {"observed_research_question": "Coaching pickup: H1->H2 share shift toward BEST vs AVOID", "auto_outcome_status": "rejected", "observed_hypothesis": "After suppression, teams shift volume toward the sheet BEST counter and away from AVOID.", "observed_result": "% shifted more toward BEST 51.6%; % used more AVOID 22.4%. Avg best pickup +0.0024 pp; BEST share 10.0%->10.2%. PO AVOID share within AVOID+INSUFF 13.4%->13.7% (+0.3 pp); BEST 12.9%->12.8%. RS AVOID +1.1 pp; BEST 13.1%-> [cut; read_family for the full text]", "auto_failure_mechanism": "B_powered_null (adequately powered null result)", "observed_failure_evidence": "BEST pickup +0.24 pp is essentially zero; teams do not shift toward BEST; AVOID ticks up slightly.", "observed_sample_and_power": "n=591 triggers with BEST defined", "auto_validation_status": "same_pipeline_validation; evidence: repeat runs of the design agree", "observed_verdict": "null", "auto_confidence": "high (0.95)"}, "relationships": [{"rel": "auto_related_family", "node": "FAM:SF08"}]}, {"id": "FAM:SF08", "label": "Study family SF08: Season adapter profiles (BEST-share consistency across seasons)", "score": 1.07, "reached_via": ["request matches the question or hypothesis of FAM:SF08 (0.71)", "FAM:SF-APPS-030 auto_related_family (record_link_extends) FAM:SF08"], "attributes": {"observed_research_question": "Season adapter profiles (BEST-share consistency across seasons)", "auto_outcome_status": "not a hypothesis test", "observed_hypothesis": "Teams' post-trigger BEST vs AVOID mix is a stable coaching signature across seasons.", "observed_result": "Top mean BEST share: BOS 15.7% (10 dirs, win 70%), LAL 15.5%, GSW 13.8%. Bottom: HOU 2.5%, MIL 3.5%, LAC 4.1%. DEN 4.9% BEST / 70.8% INSUFF yet 62% win. ORL AVOID share 59.3%, 0% win.", "auto_failure_mechanism": "E_unclear (mechanism unclear from the records)", "observed_failure_evidence": "No inferential test of stability vs noise; win% not identified with BEST share (IND 4.5% BEST, 71% win).", "observed_sample_and_power": "19 teams with n>=2 seasons", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_verdict": "descriptive", "observed_failure_type": "E_unclear"}, "relationships": [{"rel": "auto_related_family", "node": "FAM:SF-APPS-027"}, {"rel": "auto_related_family", "node": "FAM:SF-APPS-030"}, {"rel": "auto_related_family", "node": "FAM:SF05"}]}, {"id": "FAM:SF01", "label": "Study family SF01: Suppression is not regression to mean: matched-control excess", "score": 0.714, "reached_via": ["request matches the question or hypothesis of FAM:SF01 (0.71)"], "attributes": {"observed_research_question": "Suppression is not regression to mean: matched-control excess", "auto_outcome_status": "supported", "observed_hypothesis": "The H1-to-H2 PPP drop after a trigger exceeds the drop of a matched control, beyond what RTM predicts.", "observed_result": "PO C: excess +0.680 [0.619, 0.740], n=534, t=22.11; RTM pred 0.097 of 0.626 drop (15.5%), excess 0.529. Full graph unconstrained +0.628 n=9,900 then Z1+Z2 +0.625 n=9,111. H1-balanced caliper 0.10 +0.408 [0.378, 0.438], 1 [cut; read_family for the full text]", "auto_failure_mechanism": "D_positive (no failure: positive result)", "observed_failure_evidence": "Excess drops from +0.625 unconstrained to +0.408 when balanced on H1 PPP, but the cluster CI excludes 0; Z1+Z2 moved excess only +0.004 vs pre-fix +0.404.", "observed_verdict": "supported", "auto_confidence": "high (1.0)"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:small_sample"}, {"rel": "auto_has_risk", "node": "RISK:PLACEBO_DEPENDENCE"}, {"rel": "auto_has_risk", "node": "RISK:SAMPLE_SIZE_POWER"}]}, {"id": "FAM:SF-CHT-039", "label": "Study family SF-CHT-039: Series-level AVOID share vs winning (talent confound)", "score": 0.459, "reached_via": ["request matches RQC:RQC-103 (0.73); FAM:SF-CHT-039 auto_addresses_question RQC:RQC-103"], "attributes": {"observed_research_question": "Series-level AVOID share vs winning (talent confound)", "auto_outcome_status": "untestable", "observed_hypothesis": "Higher AVOID share predicts losing, independent of team quality.", "observed_result": "Game-level rho=-0.19 p=0.008 (inflated n, team-quality confound). Series-level rho=-0.26 p=0.07 (n=50, underpowered; ~80 series needed for p<0.05). Low AVOID-share bin 52.6% vs 25-50% bin 37.0%.", "auto_failure_mechanism": "A_unanswerable (question not answerable with the data or design)", "observed_failure_evidence": "Series n=50 p=0.07; still confounded by team quality (OKC disciplined and good).", "observed_sample_and_power": "n=50 series; stated need ~80 for p<0.05", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_verdict": "inconclusive"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:confounding"}, {"rel": "auto_limited_by", "node": "LIM:small_sample"}, {"rel": "auto_has_risk", "node": "RISK:CONFOUNDING"}, {"rel": "auto_has_risk", "node": "RISK:SAMPLE_SIZE_POWER"}]}, {"id": "FAM:SF-APPS-032", "label": "Study family SF-APPS-032: CUT depletion / decay hypothesis (feasibility, not efficiency)", "score": 0.358, "reached_via": ["FAM:SF-APPS-023 auto_related_family (record_link_related_to) FAM:SF-APPS-032"], "attributes": {"observed_research_question": "CUT depletion / decay hypothesis (feasibility, not efficiency)", "auto_outcome_status": "rejected", "observed_hypothesis": "CUT PPP decays across successive H2 runs, so the playsheet should rotate off CUT to SPOT_UP.", "observed_result": "CUT PPP stable 1.60-1.71 for runs 1-5 (all n>=14); runs 6+ n=4/2/0. 62.0% of team-halves never crossed below SPOT_UP (n=405). Depletion-adjusted rho -0.0415 vs baseline -0.2737 (degraded 0.2322). DP -6.7 pts/100 vs stati [cut; read_family for the full text]", "auto_failure_mechanism": "B_powered_null (adequately powered null result)", "observed_failure_evidence": "No efficiency cliff; constraint is opportunity (~3-5 CUT per half). DP was built on fabricated decay.", "observed_sample_and_power": "311 games; CUT runs 6+ essentially unobserved", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:label_or_classification_error"}, {"rel": "auto_has_risk", "node": "RISK:LABEL_ERROR"}]}, {"id": "FAM:SF02", "label": "Study family SF02: Cost of ignoring suppression: continue rate and points lost", "score": 0.357, "reached_via": ["FAM:SF01 auto_related_family (record_link_related_to) FAM:SF02"], "attributes": {"observed_research_question": "Cost of ignoring suppression: continue rate and points lost", "auto_outcome_status": "inconclusive", "observed_hypothesis": "After a suppression trigger, teams keep running the suppressed play at near-H1 volume and lose several points per event.", "observed_result": ["[APPA-040] PO: 735 events; Group A 683 (93%) H1 1.522 to H2 0.876, cost/poss 0.646, ~8.2 H2 poss, ~97% H1 volume, ~5.4 pts/trigger; real actionable ~6.1 pts (5.3 keep-calling + 0.8 AVOID vs BEST). RS continue 93.1% (2,94 [cut; read_family for the full text]", "[APPS-021] Group A: H1 1.522 -> post-trigger 0.876, cost 0.646 PPP/poss, 5.16 pts/trigger (t=48.172, p=0.0000, n=683). Pivot vs continue overall H2 1.074 vs 1.043, MW p=0.2642. Locked row-mean (n>=5): H1 1.48->H2 0.85, d [cut; read_family for the full text]", "[CHT-040] H1-H2 drop t=48.172 p=0.0000 (n=683). Pivoting improve H2? Mann-Whitney p=0.2642 (not significant)."]}, "relationships": []}], "n_results": 10}

